{
  "rubric_name": "Software Engineer Performance Review Rubric",
  "evaluation_period": "Q1 2024",
  "criteria": [
    {
      "name": "Code Quality",
      "description": "Correctness, readability, maintainability, adherence to standards, and minimal technical debt.",
      "levels": {
        "Exceeds Expectations": "Consistently delivers clean, well-structured code with zero critical bugs; excellent readability; proactively refactors for maintainability; fully follows team standards; includes clear, concise documentation where needed.",
        "Meets Expectations": "Delivers functional code with minimal bugs; reasonable readability and structure; follows standards appropriately; minor technical debt occasionally present; documentation is adequate for routine tasks.",
        "Needs Improvement": "Frequently delivers code with significant bugs or poor readability; inconsistent adherence to standards; noticeable technical debt accumulation; documentation is incomplete or unclear; requires frequent fixes or rework."
      }
    },
    {
      "name": "Problem Solving",
      "description": "Ability to analyze root causes, design efficient solutions, handle edge cases, and implement correctly.",
      "levels": {
        "Exceeds Expectations": "Consistently identifies root causes quickly; proposes innovative, optimal solutions; handles complex edge cases; implements with thorough testing; documents reasoning and trade-offs; reduces debugging time.",
        "Meets Expectations": "Effectively solves assigned problems; finds correct solutions; handles typical edge cases; tests adequately for functionality; communicates approach clearly during reviews.",
        "Needs Improvement": "Struggles to pinpoint root causes; solutions are often incomplete, inefficient, or buggy; misses common edge cases; minimal or inconsistent testing; relies heavily on guidance for resolution."
      }
    },
    {
      "name": "Collaboration & Communication",
      "description": "Clarity in updates, constructive participation in discussions, responsiveness to teammates, and support for team goals.",
      "levels": {
        "Exceeds Expectations": "Proactively shares progress, blockers, and ideas in concise updates; actively listens; helps resolve teammates' issues quickly; fosters positive, solution-focused discussions; provides helpful feedback without delay.",
        "Meets Expectations": "Regularly provides clear updates; participates meaningfully in discussions; resolves minor blockers with reasonable support; collaborates well with peers; responds to communication requests in a timely manner.",
        "Needs Improvement": "Communicates infrequently or unclearly; misses or delays updates; struggles to participate constructively; may create confusion; requires frequent reminders to engage or respond; limited support for teammates."
      }
    },
    {
      "name": "Delivery & Reliability",
      "description": "Consistency in meeting deadlines, managing workload, and fulfilling committed deliverables.",
      "levels": {
        "Exceeds Expectations": "Consistently delivers ahead of or on schedule; anticipates risks early; adjusts scope proactively when needed; high reliability in meeting all commitments; minimal last-minute changes.",
        "Meets Expectations": "Generally meets deadlines; manages workload effectively; occasional minor delays due to unforeseen issues, but recovers quickly; commitments are fulfilled as promised most of the time.",
        "Needs Improvement": "Frequently misses deadlines or delivers late; struggles with workload prioritization; delays often require re-prioritization; low reliability in meeting stated commitments; needs frequent adjustments."
      }
    },
    {
      "name": "Learning & Growth",
      "description": "Initiative to improve skills, adopt relevant tools/technologies, and apply learnings effectively to current work.",
      "levels": {
        "Exceeds Expectations": "Actively seeks feedback; independently learns new tools/concepts needed for tasks; applies learnings immediately to improve code/processes; shares concise knowledge with team; shows measurable skill improvement over time.",
        "Meets Expectations": "Responds to feedback; learns necessary tools for assigned tasks through provided resources; applies basics correctly; participates in team training when offered; shows steady, expected skill progression.",
        "Needs Improvement": "Rarely seeks feedback; struggles to learn new tools without extensive hand-holding; limited application of training; little to no observable skill improvement over the review period; relies on others for basic guidance."
      }
    }
  ],
  "overall_rating_guidance": {
    "scale": "Exceeds Expectations (4), Meets Expectations (3), Needs Improvement (2), Developing (1)",
    "note": "Overall rating should reflect consistent performance across all criteria. Weight criteria based on role relevance (e.g., Delivery may be higher for feature teams, Learning for growth roles). Avoid averaging; use judgment on pattern (e.g., consistently strong in Code Quality but Needs Improvement in Delivery warrants 'Needs Improvement' overall if delivery is critical)."
  },
